# Let me analyze the grid for patterns - check if certain colors form recognizable shapes
from collections import deque

def get_connected_regions(grid, color):
    """Find all connected cells of given color"""
    rows, cols = len(grid), len(grid[0])
    regions = []
    visited = set()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == color and (r,c) not in visited:
                region = [(r,c)]
                queue = deque([(r,c)])
                while queue:
                    cr, cc = queue.popleft()
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                region.append((nr, nc))
                                queue.append((nr, nc))
                regions.append(region)
    return regions

